import copy
import math
from numbers import Real


class NumericDataset:
    def __init__(self, rows):
        if not isinstance(rows, list):
            raise TypeError("rows must be a list")
        if not rows:
            raise ValueError("rows must not be empty")
        expected = None
        for row in rows:
            if not isinstance(row, dict):
                raise TypeError("each row must be a dictionary")
            if "label" not in row:
                raise ValueError("each row must contain label")
            label = row["label"]
            if isinstance(label, bool) or not isinstance(label, int) or label not in (0, 1):
                raise ValueError("label must be integer 0 or 1")
            keys = set(row) - {"label"}
            if not keys:
                raise ValueError("at least one feature is required")
            if any(not isinstance(key, str) for key in keys):
                raise TypeError("feature names must be strings")
            if expected is None:
                expected = keys
            elif keys != expected:
                raise ValueError("feature keys must be consistent")
            for key in keys:
                value = row[key]
                if isinstance(value, bool) or not isinstance(value, Real):
                    raise TypeError("features must be real numbers")
                if not math.isfinite(value):
                    raise ValueError("features must be finite")
        self._rows = copy.deepcopy(rows)
        self._names = sorted(expected)

    def matrix(self):
        features = [[row[name] for name in self._names] for row in self._rows]
        labels = [row["label"] for row in self._rows]
        return features, labels, list(self._names)

    def split(self, fraction=0.75):
        if isinstance(fraction, bool) or not isinstance(fraction, Real):
            raise TypeError("fraction must be real")
        if not math.isfinite(fraction) or not 0 < fraction < 1:
            raise ValueError("fraction must be finite and between zero and one")
        boundary = int(len(self._rows) * fraction)
        if boundary == 0 or boundary == len(self._rows):
            raise ValueError("both partitions must be non-empty")
        return NumericDataset(copy.deepcopy(self._rows[:boundary])), NumericDataset(copy.deepcopy(self._rows[boundary:]))


class CentroidBinaryClassifier(NumericDataset):
    def __init__(self, rows):
        super().__init__(rows)
        self._centroids = None

    def fit(self):
        features, labels, _ = self.matrix()
        if set(labels) != {0, 1}:
            raise ValueError("both labels are required")
        centroids = {}
        for label in (0, 1):
            selected = [row for row, current in zip(features, labels) if current == label]
            centroids[label] = [sum(column) / len(selected) for column in zip(*selected)]
        self._centroids = centroids
        return self

    def _validate_features(self, feature_rows):
        if not isinstance(feature_rows, list):
            raise TypeError("feature_rows must be a list")
        checked = []
        for row in feature_rows:
            if not isinstance(row, list):
                raise TypeError("each feature row must be a list")
            if len(row) != len(self._names):
                raise ValueError("feature row has incorrect length")
            for value in row:
                if isinstance(value, bool) or not isinstance(value, Real):
                    raise TypeError("features must be real numbers")
                if not math.isfinite(value):
                    raise ValueError("features must be finite")
            checked.append(list(row))
        return checked

    def predict(self, feature_rows):
        if self._centroids is None:
            raise RuntimeError("classifier has not been fitted")
        checked = self._validate_features(feature_rows)
        predictions = []
        for row in checked:
            distances = {
                label: sum((value - center) ** 2 for value, center in zip(row, centroid))
                for label, centroid in self._centroids.items()
            }
            predictions.append(0 if distances[0] >= distances[1] else 1)
        return predictions

    def score(self, feature_rows, labels):
        predictions = self.predict(feature_rows)
        if not isinstance(labels, list):
            raise TypeError("labels must be a list")
        if len(predictions) != len(labels):
            raise ValueError("lengths must match")
        if not labels:
            raise ValueError("inputs must not be empty")
        for label in labels:
            if isinstance(label, bool) or not isinstance(label, int) or label not in (0, 1):
                raise ValueError("labels must be integer 0 or 1")
        return sum(predicted == actual for predicted, actual in zip(predictions, labels)) / len(labels)

